class BrowserSession:
    """管理 Playwright 浏览器会话。"""

    def __init__(self) -> None:
        self._playwright = None
        self._browser: Browser | None = None
        self._context: BrowserContext | None = None
        self._page: Page | None = None

    async def open(self, url: str, window_index: int = 0, total_windows: int = 1) -> Page:
        try:
            self._playwright = await async_playwright().start()
            self._browser = await self._playwright.chromium.launch(headless=False)

            # 计算窗口布局：横向平铺，不重叠
            viewport_width = 600
            viewport_height = 700
            gap = 10
            x_pos = 50 + window_index * (viewport_width + gap)
            y_pos = 50

            self._context = await self._browser.new_context(
                viewport={"width": viewport_width, "height": viewport_height},
            )
            self._page = await self._context.new_page()

            # 设置窗口位置（通过 CDP）
            try:
                cdp = await self._page.context.new_cdp_session(self._page)
                window_info = await cdp.send("Browser.getWindowForTarget")
                await cdp.send("Browser.setWindowBounds", {
                    "windowId": window_info["windowId"],
                    "bounds": {"left": x_pos, "top": y_pos, "width": viewport_width, "height": viewport_height},
                })
            except Exception:
                pass  # CDP 定位失败不影响主流程

            await self._page.goto(url)
            return self._page
        except Error as e:
            await self.close()
            raise BrowserError("unknown", f"浏览器启动失败: {e}") from e

    async def wait_for_login(self, jira_host: str) -> None:
        if self._page is None:
            raise BrowserError("unknown", "浏览器未打开，请先调用 open()")
        try:
            await self._page.wait_for_url(
                lambda url: jira_host in url and "login" not in url,
                timeout=0,
            )
        except Error as e:
            raise BrowserError("unknown", f"用户在登录完成前关闭了浏览器: {e}") from e

    async def get_cookies(self) -> list[dict]:
        if self._context is None:
            raise BrowserError("unknown", "浏览器上下文不可用，请先调用 open()")
        try:
            return await self._context.cookies()
        except Error as e:
            raise BrowserError("unknown", f"获取 Cookie 失败: {e}") from e

    async def close(self) -> None:
        if self._browser is not None:
            try:
                await self._browser.close()
            except Error:
                pass
            self._browser = None
        if self._playwright is not None:
            try:
                await self._playwright.stop()
            except Error:
                pass
            self._playwright = None
        self._context = None
        self._page = None
