1055	static int media_recorder_start(MediaRecorderContext* ctx)
1056	{
1057	    int ret = AVERROR(EPERM);
1058	    int i;
1059	
1060	    if (ctx->state != MEDIA_RECORDER_STATE_PREPARED && ctx->state != MEDIA_RECORDER_STATE_PAUSED)
1061	        goto out;
1062	
1063	    if (ctx->state == MEDIA_RECORDER_STATE_PREPARED) {
1064	        for (i = 0; i < ctx->nb_streams; i++) {
1065	            if (ctx->streams[i].type == AVMEDIA_TYPE_AUDIO)
1066	                ret = media_recorder_start_astream(ctx, i);
1067	            else
1068	                ret = media_recorder_start_vstream(ctx, i);
1069	            if (ret < 0)
1070	                goto out;
1071	        }
1072	
1073	        /* For audio-only, write_header is deferred to on_event_cb
1074	         * when the first encoded pkt arrives with extradata.
1075	         * For video (or audio codecs without extradata), write now. */
1076	        if (ctx->video_idx >= 0 && ctx->audio_idx < 0) {
1077	            ret = avformat_write_header(ctx->format_ctx, NULL);
1078	            if (ret < 0)
1079	                goto out;
1080	            ctx->header_written = true;
1081	        }
1082	    }
1083	
1084	    if (ctx->audio_idx >= 0) {
1085	        ret = audio_record_start(ctx->audio_input);
1086	        if (ret < 0) {
1087	            MEDIA_ERR("ctx %p audio_record_start failed, ret %d.\n", ctx, ret);
1088	            goto out;
1089	        } else
1090	            MEDIA_INFO("ctx %p audio_record_start success.\n", ctx);
1091	    }
1092	
1093	    ctx->state = MEDIA_RECORDER_STATE_STARTED;
1094	
1095	out:
1096	    media_recorder_event_cb(ctx, MEDIA_EVENT_STARTED, ret, NULL);
1097	    return ret;
1098	}
