1139	static int media_recorder_send_cmd(MediaRecorderContext* ctx, const int cmd, const void* data, size_t size)
1140	{
1141	    RecorderCmd *msg, *tmp;
1142	    int cnt = 0;
1143	
1144	    msg = av_malloc(sizeof(RecorderCmd) + size);
1145	    if (!msg)
1146	        return AVERROR(ENOMEM);
1147	
1148	    msg->cmd = cmd;
1149	
1150	    if (data && size)
1151	        memcpy(msg->data, data, size);
1152	
1153	    SIMPLEQ_FOREACH(tmp, &ctx->cmd_queue, entry)
1154	    cnt++;
