1156	        av_freep(&msg);
1157	        return AVERROR(ENOMEM);
1158	    }
1159	
1160	    SIMPLEQ_INSERT_TAIL(&ctx->cmd_queue, msg, entry);
1161	
1162	    return 0;
1163	}
