432	 * @brief Connection available to accept a data pipe.
433	 */
434	static void media_uv_stream_listen_connection_cb(uv_stream_t* stream, int ret)
435	{
436	    MediaListenPriv* listener = uv_handle_get_data((uv_handle_t*)stream);
437	    MediaStreamPriv* priv = listener->priv;
438	
439	    if (ret < 0 || !priv || priv->pipe) { /* Only one listener meets error. */
440	        media_uv_stream_listen_remove(listener);
441	        return;
442	    }
443	
444	    priv->pipe = zalloc(sizeof(uv_pipe_t));
445	    if (!priv->pipe) {
446	        media_uv_stream_listen_clear(priv, NULL);
447	        return;
448	    }
449	
450	    ret = uv_pipe_init(priv->loop, priv->pipe, 0);
451	    if (ret < 0) {
452	        free(priv->pipe);
453	        priv->pipe = NULL;
454	        media_uv_stream_listen_clear(priv, NULL);
455	        return;
456	    }
457	
458	    ret = uv_accept(stream, (uv_stream_t*)priv->pipe);
459	    if (ret < 0) {
460	        media_uv_stream_close_pipe(priv);
461	        media_uv_stream_listen_clear(priv, NULL);
462	        return;
463	    }
464	
465	    MEDIA_INFO("%s:%p listener:%p accept:%p\n", priv->name, priv, listener, priv->pipe);
466	    media_uv_stream_listen_clear(priv, listener); /* Clear redundant listeners. */
467	    if (!priv->on_connection) {
468	        media_uv_stream_close_pipe(priv);
469	        return;
470	    }
471	
472	    priv->on_connection(priv->cookie, 0, priv->pipe);
473	    priv->on_connection = NULL;
474	}
