611	/* Drain the capture fd (non-blocking). */
612	static int media_recorder_read(MediaRecorderContext* ctx)
613	{
614	    uint64_t cnt = 1;
615	    ssize_t n = 0;
616	
617	    for (;;) {
618	        AVPacket* pkt;
619	
620	        if (ctx->state != MEDIA_RECORDER_STATE_STARTED
621	            && ctx->state != MEDIA_RECORDER_STATE_PAUSED)
622	            break;
623	
624	        pkt = av_packet_alloc();
625	        if (!pkt || av_new_packet(pkt, ctx->fragment_size) < 0) {
626	            av_packet_free(&pkt);
627	            ctx->fail_code = AVERROR(ENOMEM);
628	            ctx->exit = 1;
629	            break;
630	        }
631	
632	        n = audio_record_read_data(ctx->audio_input, pkt->data,
633	            ctx->fragment_size);
634	        if (n <= 0) {
635	            av_packet_free(&pkt);
636	            break;
637	        }
638	
639	        av_shrink_packet(pkt, n);
640	        media_recorder_stamp_and_enqueue(ctx, pkt);
641	        if (ctx->exit)
642	            break;
643	    }
644	
645	    /* Wake the mux loop to drain pkt_queue this iteration. */
646	    write(ctx->event_fd, &cnt, sizeof(cnt));
647	
648	    if (n < 0 && n != -EAGAIN && n != -EINTR)
649	        return (int)n;
650	
651	    return 0;
652	}
