1487	static void media_recorder_poll(MediaRecorderContext* ctx)
1488	{
1489	    int audio_fd = audio_record_get_fd(ctx->audio_input);
1490	    struct pollfd fds[3];
1491	    int nfds = 2;
1492	    int ret;
1493	
1494	    fds[0].fd = ctx->tran_fd;
1495	    fds[0].events = POLLIN;
1496	    fds[0].revents = 0;
1497	    fds[1].fd = ctx->event_fd;
1498	    fds[1].events = POLLIN;
1499	    fds[1].revents = 0;
1500	    /* Only poll the cross-core capture fd while recording; a stopped device
1501	     * can keep signalling POLLIN with empty buffers, which would spin the
1502	     * loop.  Outside STARTED/PAUSED the session waits for the next command. */
1503	    if (audio_fd >= 0
1504	        && (ctx->state == MEDIA_RECORDER_STATE_STARTED
1505	            || ctx->state == MEDIA_RECORDER_STATE_PAUSED)) {
1506	        fds[2].fd = audio_fd;
1507	        fds[2].events = POLLIN;
1508	        fds[2].revents = 0;
1509	        nfds = 3;
1510	    }
1511	
1512	    ret = poll(fds, nfds, -1);
1513	    if (ret == -1) {
1514	        MEDIA_ERR("ctx %p poll failed err=%d\n", ctx, -errno);
1515	    } else if (ret == 0)
1516	        MEDIA_DEBUG("ctx %p poll timeout\n", ctx);
1517	
1518	    for (int i = 0; i < nfds; i++) {
1519	        if (!fds[i].revents)
1520	            continue;
1521	
1522	        ret = media_recorder_poll_available(ctx, &fds[i]);
1523	        if (ret < 0 && ret != -EAGAIN && ret != -EPIPE)
1524	            MEDIA_ERR("ctx %p poll_available failed %d\n", ctx, ret);
1525	    }
1526	}
