1528	static void* media_recorder_thread(void* arg)
1529	{
1530	    MediaRecorderContext* ctx = (MediaRecorderContext*)arg;
1531	    RecorderCmd* msg;
1532	    MEDIA_INFO("ctx %p create recorder thread.\n", ctx);
1533	
1534	    while (1) {
1535	        if (media_recorder_is_exit(ctx))
1536	            break;
1537	
1538	        media_recorder_poll(ctx);
1539	
1540	        while ((msg = SIMPLEQ_FIRST(&ctx->cmd_queue)) != NULL) {
1541	            SIMPLEQ_REMOVE_HEAD(&ctx->cmd_queue, entry);
1542	            media_recorder_proc_cmd(ctx, msg);
1543	        }
1544	
1545	        if (media_recorder_dat_valid(ctx) && media_recorder_proc_dat(ctx) == AVERROR_EOF) {
1546	            ctx->exit = 1;
1547	        }
1548	
1549	        if (ctx->fail_code) {
1550	            media_recorder_fail(ctx, ctx->fail_code);
1551	            ctx->fail_code = 0;
1552	        }
1553	    }
1554	
1555	    media_recorder_close(ctx);
1556	
1557	    media_recorder_ctx_release(ctx);
1558	
1559	    MEDIA_INFO("ctx %p %s recorder thread exit.\n", ctx, ctx->name);
1560	    return NULL;
1561	}
