910	static int media_recorder_proc_apkt(MediaRecorderContext* ctx)
911	{
912	    AVPacket pkt;
913	    int ret;
914	
915	    if (ctx->audio_idx < 0 || ctx->audio_idx >= ctx->nb_streams)
916	        return 0;
917	
918	    pthread_mutex_lock(&ctx->mutex);
919	    while (packet_queue_get(&ctx->pkt_queue, &pkt) == 0) {
920	        pthread_mutex_unlock(&ctx->mutex);
921	
922	        ret = media_recorder_write_header(ctx, &pkt);
923	        if (ret < 0) {
924	            av_packet_unref(&pkt);
925	            return media_recorder_fail(ctx, ret);
926	        }
927	
928	        if (ctx->state == MEDIA_RECORDER_STATE_PAUSED) {
929	            av_packet_unref(&pkt);
930	            pthread_mutex_lock(&ctx->mutex);
931	            continue;
932	        }
933	
934	        pkt.stream_index = ctx->audio_idx;
935	        if (pkt.pts != AV_NOPTS_VALUE)
936	            ctx->current_ms = av_rescale_q(pkt.pts, (AVRational) { 1, 1000000 }, (AVRational) { 1, 1000 });
937	        av_packet_rescale_ts(&pkt,
938	            (AVRational) { 1, 1000000 },
939	            ctx->format_ctx->streams[pkt.stream_index]->time_base);
940	
941	        ret = av_write_frame(ctx->format_ctx, &pkt);
942	        av_packet_unref(&pkt);
943	        if (ret < 0) {
944	            /* Stop interrupts the muxer I/O as AVERROR_EXIT; that is a normal
945	             * stop, not a write failure, so don't take the fail path. */
946	            if (ret == AVERROR_EXIT)
947	                return 0;
948	            MEDIA_ERR("av_write_frame failed: %d\n", ret);
949	            return media_recorder_fail(ctx, ret);
950	        }
951	
952	        pthread_mutex_lock(&ctx->mutex);
953	    }
954	    pthread_mutex_unlock(&ctx->mutex);
955	
956	    return 0;
957	}
