        """Overlays a nested dictionary using dict2 on top of dict1

        Args:
            dict1 (dict): base dictionary
            dict2 (dict): dictionary to be overlayed with

        Returns:
            dict: overlayed dictionary
        """
        for k, v in dict2.items():
            if isinstance(v, Mapping):
                dict1[k] = self.update_nested_dict(dict1.get(k, {}), v)
            else:
