    def select_individual_tests(self, print_table: bool = True) -> None:
        """Execute individual test cases selected by -i indices.

        When -m is specified, indices are relative to that module's case list.
        When -m is absent, indices are global across all discovered tests.
        All selected cases are executed in a single pytest session.
        """
        test_list = runner.list_tests(print_table=print_table)
        if not test_list:
            logging.error("No tests found to select from")
            return

        # Build testname -> testcase mapping for extra_opts lookup
        test_cases_for_name = {tc["testname"]: tc for tc in self.testcases}

        try:
            # Collect all selected test paths and extra_opts
            test_paths = []
            all_extra_opts = []
            for idx in args.select_individual_tests:
                if idx not in test_list:
                    logging.error(f"Invalid test index: {idx}")
                    continue
                test_info = test_list[idx]
                test_paths.append(test_info)
                test_case = test_info[test_info.index("::") + 2:]
                if test_case in test_cases_for_name:
                    all_extra_opts.extend(
                        test_cases_for_name[test_case].get("extra_opts", [])
                    )

            if not test_paths:
                logging.error("No valid test cases selected")
                return

            # Use module name from -m for correct reporting/teardown;
            # fall back to first test case name when -m is absent.
            module_name = (
                self.modules_list[0]
                if hasattr(self, "modules_list") and self.modules_list
                else test_paths[0].split("::")[1]
            )
            # Deduplicate extra_opts (e.g. --run_in_cores may repeat)
            pytest_args = " ".join(sorted(set(all_extra_opts))) if all_extra_opts else None
            # coralsea_result: this selection IS the planned set for -i runs;
            # module_name is the same string check_failure_option_and_run_test
            # records as completed, so planned and completed agree on a full run.
            self.valid_modules[module_name] = test_paths[0]
            for _ in range(args.loops):
                runner.execute_single_test_module(
                    module_name, " ".join(test_paths), pytest_args
                )
        except KeyError as ex:
            logging.error(f"Test index not found in test list: {ex}")
        except Exception as ex:
            logging.exception(f"Failed to execute selected test cases: {ex}")

