679	static void mediatool_uv_recorder_read_cb(uv_stream_t* stream, ssize_t nread, const uv_buf_t* buf)
680	{
681	    mediatool_chain_t* chain = uv_handle_get_data((uv_handle_t*)stream);
682	    mediatool_t* mediatool = chain->data;
683	    uv_buf_t iov;
684	
685	    if (nread == UV_ENOBUFS) {
686	        usleep(1000);
687	        return;
688	    }
689	    assert(nread <= MEDIATOOL_MAX_SIZE);
690	    chain->buf = buf->base;
691	    uv_req_set_data((uv_req_t*)&chain->fs_req, chain);
692	    if ((nread < 0) || (chain->running == false)) {
693	        if (nread != UV_EOF)
694	            printf("[%s][%d] Recorder read error %s\n", __func__, __LINE__, uv_err_name(nread));
695	        free(chain->buf);
696	        chain->buf = NULL;
697	        /* One owner for the stream file: close_handler also clears chain->fd,
698	         * so a late read callback cannot close the fd of the next prepare.
699	         */
700	        mediatool_uv_common_close_handler(chain);
701	        return;
702	    }
703	
704	    iov = uv_buf_init(buf->base, nread);
705	    uv_fs_write(&mediatool->loop, &chain->fs_req, chain->fd,
706	        &iov, 1, -1, mediatool_uv_recorder_write_cb);
707	}
