1347	static ssize_t mediatool_process_data(int fd, bool player,
1348	    void* data, size_t len)
1349	{
1350	    int event = player ? POLLOUT : POLLIN;
1351	    struct pollfd fds[1];
1352	    int ret;
1353	
1354	    fds[0].fd = fd;
1355	    fds[0].events = event;
1356	    ret = poll(fds, 1, -1);
1357	
1358	    if (ret < 0)
1359	        return -errno;
1360	
1361	    if (player)
1362	        return send(fd, data, len, 0);
1363	    else
1364	        return recv(fd, data, len, 0);
1365	}
